{
  "name": "obligations-pane",
  "version": "0.7.0",
  "description": "The memory pane: a side pane over a memory-kit home's memory, one tab per tier (obligations, scratchpad, commitments, rules, lessons, facts, keys, secrets); read-only",
  "author": {
    "name": "Mihkel Putrinš"
  },
  "types": "./types/index.d.ts",
  "userConfig": {
    "agentName": {
      "type": "string",
      "title": "Agent name",
      "description": "The name the footer shows for this session's main agent. A home's agent_name: in its memory-kit.conf wins over it. Empty uses the working directory's name.",
      "default": ""
    },
    "memoryDir": {
      "type": "string",
      "title": "Memory directory",
      "description": "The kit home's memory directory, for a session that runs outside the home. Relative paths resolve against the session's working directory. Empty reads memory_dir from <cwd>/memory-kit.conf, else <cwd>/memory.",
      "default": ""
    },
    "autoOpen": {
      "type": "boolean",
      "title": "Open at session start",
      "description": "Open the pane when a session starts in a folder that has an obligations file (it still waits for a wide enough terminal). /memory-pane or /obligations opens it any time.",
      "default": true
    },
    "checkUpdates": {
      "type": "boolean",
      "title": "Check for kit releases",
      "description": "At most every 6 hours, ask the kit's upstream (memory-kit.conf upstream:, default codeberg.org mitselek/memory-kit) for its release tags, and show a newer one in the header. It only tells; it never pulls. Off makes no request at all.",
      "default": true
    }
  }
}

